from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod
import itertools

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


def hamming(a: List[int], b: List[int]) -> int:
    return sum(x != y for x, y in zip(a, b))

class ExclusivityProbesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # persistent state
        self.found_particles: List[List[int]] = []
        self.probed_nos: set = set()

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        # First move: no previous guess
        if prev_guess is None:
            next_guess = [0] * dimension
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_guess, type='custom')]
            )

        # Update history
        key = tuple(prev_guess)
        if is_particle:
            if key not in [tuple(x) for x in self.found_particles]:
                self.found_particles.append(prev_guess.copy())
        else:
            self.probed_nos.add(key)

        # If we have found all particles, we still return something but game should end
        if len(self.found_particles) >= num_particles:
            # no more probes needed; just repeat a known particle
            next_guess = self.found_particles[0]
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=next_guess, type='custom')]
            )

        # Generate next candidate lexicographically
        next_guess = None
        for bits in itertools.product([0,1], repeat=dimension):
            if bits in self.probed_nos:
                continue
            if bits in [tuple(x) for x in self.found_particles]:
                continue
            # enforce exclusion distance from all found
            too_close = False
            for f in self.found_particles:
                if hamming(bits, f) < distance:
                    too_close = True
                    break
            if too_close:
                continue
            # this is a valid next probe
            next_guess = list(bits)
            break

        # Fallback: if no candidate found (should not happen), pick all-zero or first particle
        if next_guess is None:
            if self.found_particles:
                next_guess = self.found_particles[0]
            else:
                next_guess = [0] * dimension

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

