        data = message.message[0].data
        # Extract the game parameters
        dimension = data['dimension']
        num_particles = data['num_particles']
        distance = data['distance']
        prev_guess = data['guess']
        is_particle = data['is_particle']

        model = self._model
        # Initialize our state on first call
        if not hasattr(model, 'tested'):
            model.tested = set()        # integers we've probed
        if not hasattr(model, 'found'):
            model.found = set()         # integers where we found particles
        if not hasattr(model, 'last_index'):
            model.last_index = 0        # resume scanning from here

        # Helper converters
        def bits_to_int(bits: List[int]) -> int:
            return int(''.join(str(b) for b in bits), 2)

        def int_to_bits(x: int, dims: int) -> List[int]:
            return [int(b) for b in bin(x)[2:].zfill(dims)]

        # Record the previous result
        if prev_guess is not None:
            g_int = bits_to_int(prev_guess)
            model.tested.add(g_int)
            if is_particle:
                model.found.add(g_int)

        # Find the next valid probe
        next_guess = None
        space_size = 1 << dimension
        # First pass: continue from last_index
        for idx in range(model.last_index, space_size):
            if idx in model.tested:
                continue
            valid = True
            for f in model.found:
                # skip if too close to any found particle
                if (idx ^ f).bit_count() < distance:
                    valid = False
                    break
            if not valid:
                continue
            # found our next probe
            model.last_index = idx + 1
            next_guess = int_to_bits(idx, dimension)
            break
        # If we wrapped around without success, scan from zero
        if next_guess is None:
            for idx in range(0, space_size):
                if idx in model.tested:
                    continue
                valid = True
                for f in model.found:
                    if (idx ^ f).bit_count() < distance:
                        valid = False
                        break
                if not valid:
                    continue
                model.last_index = idx + 1
                next_guess = int_to_bits(idx, dimension)
                break

        # Return the next probe
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_guess, type='custom')]
        )

